"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["57476"],{19154(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.recurso_da_etapa.regra_catalogo_invalida","status":422,"titulo":"A regra declarada n\xe3o \xe9 uma regra de prazo de recurso do cat\xe1logo"},"descricao":{"codigo":"uniplus.selecao.recurso_da_etapa.regra_catalogo_invalida","requisitos":["UNI-REQ-0080"],"oQueAconteceu":["A regra de recurso de uma etapa citou uma regra que **n\xe3o \xe9 uma regra de prazo de\\nrecurso do cat\xe1logo**. Isso acontece quando o c\xf3digo ou a vers\xe3o informados n\xe3o\\nexistem no cat\xe1logo, quando existem mas s\xe3o de outro tipo de regra, ou quando a\\nregra de recurso citada n\xe3o \xe9 a de prazo contado a partir de ato.","A regra da etapa n\xe3o descreve o prazo por texto livre: ela referencia a regra do\\ncat\xe1logo institucional, que fixa como o prazo \xe9 entendido. Referenciar uma regra\\nque n\xe3o \xe9 de prazo de recurso deixaria a regra sem uma leitura confi\xe1vel do prazo.","A regra \xe9 a mesma para os dois eventos que iniciam o prazo. Tanto a publica\xe7\xe3o do ato\\ncomo a ci\xeancia individual do parecer usam a mesma regra de prazo de recurso contado\\na partir de ato: ela diz como o prazo \xe9 contado, e o evento que o inicia \xe9 declarado\\n\xe0 parte, na pr\xf3pria regra de recurso."],"comoResolver":["A mensagem da recusa mostra o c\xf3digo e a vers\xe3o recebidos. Tr\xeas desfechos poss\xedveis:","- **Erro de grafia no c\xf3digo ou na vers\xe3o.** Corrija para o valor exato do cat\xe1logo.\\n- **A regra existe, mas \xe9 de outro tipo.** Escolha, no cat\xe1logo, a regra de prazo de\\n  recurso contado a partir de ato.\\n- **A regra de prazo ainda n\xe3o est\xe1 no cat\xe1logo.** Cadastre-a antes de configurar a\\n  etapa, e repita a defini\xe7\xe3o."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Recurso da etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);